INSERT INTO repo_modules (module_id, name, module_no, description, module_sd_id, status) VALUES ('MOD_COURSE_050_M5', 'Natural Resources and Environmental Governance', '5', 'Examines the legal concepts, institutional mechanisms, procedures, and accountability issues governing natural resources and environmental governance. The module addresses forests, biodiversity, water resources, land use, and common resources, with emphasis on their relationships, assumptions, analytical use, and application within Environmental Law and Environmental Governance.', 'MSD_COURSE_050_M5', 'Active'), ('MOD_COURSE_050_M6', 'Environmental Adjudication and Remedies', '6', 'Examines the concepts and methods required to understand and work with environmental adjudication and remedies. The module addresses tribunals, judicial review, writs, injunctions, and public interest litigation, with emphasis on their relationships, assumptions, analytical use, and application within Environmental Law and Environmental Governance.', 'MSD_COURSE_050_M6', 'Active'), ('MOD_COURSE_050_M7', 'Environmental Governance Practice', '7', 'Examines the legal concepts, institutional mechanisms, procedures, and accountability issues governing environmental governance practice. The module addresses permits, compliance systems, monitoring, reporting, and administrative decision-making, with emphasis on their relationships, assumptions, analytical use, and application within Environmental Law and Environmental Governance.', 'MSD_COURSE_050_M7', 'Active'), ('MOD_COURSE_051_M1', 'EIA Legal Framework', '1', 'Examines the legal concepts, institutional mechanisms, procedures, and accountability issues governing eia legal framework. The module addresses statutory basis, regulatory instruments, project categories, and competent authorities, with emphasis on their relationships, assumptions, analytical use, and application within Environmental Impact Assessment Law.', 'MSD_COURSE_051_M1', 'Active'), ('MOD_COURSE_051_M2', 'Screening and Scoping', '2', 'Examines the concepts and methods required to understand and work with screening and scoping. The module addresses screening, terms of reference, baseline requirements, and alternatives, with emphasis on their relationships, assumptions, analytical use, and application within Environmental Impact Assessment Law.', 'MSD_COURSE_051_M2', 'Active'), ('MOD_COURSE_051_M3', 'Impact Assessment and Environmental Appraisal', '3', 'Examines the concepts and methods required to understand and work with impact assessment and environmental appraisal. The module addresses impact prediction, cumulative impacts, risk, and mitigation hierarchy, with emphasis on their relationships, assumptions, analytical use, and application within Environmental Impact Assessment Law.', 'MSD_COURSE_051_M3', 'Active'), ('MOD_COURSE_051_M4', 'Public Participation and Consultation', '4', 'Examines the concepts and methods required to understand and work with public participation and consultation. The module addresses notice, disclosure, hearings, submissions, and procedural fairness, with emphasis on their relationships, assumptions, analytical use, and application within Environmental Impact Assessment Law.', 'MSD_COURSE_051_M4', 'Active'), ('MOD_COURSE_051_M5', 'Environmental Decision-Making', '5', 'Examines the concepts and methods required to understand and work with environmental decision-making. The module addresses appraisal committees, conditions, reasoned decisions, and judicial review, with emphasis on their relationships, assumptions, analytical use, and application within Environmental Impact Assessment Law.', 'MSD_COURSE_051_M5', 'Active'), ('MOD_COURSE_051_M6', 'Compliance and Post-Approval Monitoring', '6', 'Examines the concepts and methods required to understand and work with compliance and post-approval monitoring. The module addresses conditions, monitoring, reporting, non-compliance, and adaptive management, with emphasis on their relationships, assumptions, analytical use, and application within Environmental Impact Assessment Law.', 'MSD_COURSE_051_M6', 'Active'), ('MOD_COURSE_051_M7', 'EIA Litigation and Comparative Approaches', '7', 'Examines the concepts and methods required to understand and work with eia litigation and comparative approaches. The module addresses standing, remedies, evidentiary issues, and comparative EIA regimes, with emphasis on their relationships, assumptions, analytical use, and application within Environmental Impact Assessment Law.', 'MSD_COURSE_051_M7', 'Active'), ('MOD_COURSE_052_M1', 'Climate Governance and Legal Frameworks', '1', 'Examines the legal concepts, institutional mechanisms, procedures, and accountability issues governing climate governance and legal frameworks. The module addresses climate institutions, legislative instruments, executive policy, and federalism, with emphasis on their relationships, assumptions, analytical use, and application within Climate Change Law and Policy.', 'MSD_COURSE_052_M1', 'Active'), ('MOD_COURSE_052_M2', 'Mitigation Law and Policy', '2', 'Examines the legal concepts, institutional mechanisms, procedures, and accountability issues governing mitigation law and policy. The module addresses emissions regulation, carbon pricing concepts, energy regulation, and sectoral measures, with emphasis on their relationships, assumptions, analytical use, and application within Climate Change Law and Policy.', 'MSD_COURSE_052_M2', 'Active'), ('MOD_COURSE_052_M3', 'Adaptation and Resilience', '3', 'Examines the concepts and methods required to understand and work with adaptation and resilience. The module addresses adaptation duties, disaster risk, resilience planning, and vulnerable communities, with emphasis on their relationships, assumptions, analytical use, and application within Climate Change Law and Policy.', 'MSD_COURSE_052_M3', 'Active'), ('MOD_COURSE_052_M4', 'Climate Finance and Disclosure', '4', 'Examines the concepts and methods required to understand and work with climate finance and disclosure. The module addresses climate risk disclosure, sustainable finance, fiduciary considerations, and reporting, with emphasis on their relationships, assumptions, analytical use, and application within Climate Change Law and Policy.', 'MSD_COURSE_052_M4', 'Active'), ('MOD_COURSE_052_M5', 'International Climate Law', '5', 'Examines the legal concepts, institutional mechanisms, procedures, and accountability issues governing international climate law. The module addresses UNFCCC, Paris Agreement, nationally determined contributions, and transparency framework, with emphasis on their relationships, assumptions, analytical use, and application within Climate Change Law and Policy.', 'MSD_COURSE_052_M5', 'Active'), ('MOD_COURSE_052_M6', 'Climate Litigation and Accountability', '6', 'Examines the concepts and methods required to understand and work with climate litigation and accountability. The module addresses rights-based claims, government duties, corporate claims, and causation, with emphasis on their relationships, assumptions, analytical use, and application within Climate Change Law and Policy.', 'MSD_COURSE_052_M6', 'Active'), ('MOD_COURSE_052_M7', 'Climate Policy Implementation', '7', 'Examines the concepts and methods required to understand and work with climate policy implementation. The module addresses policy instruments, regulatory coordination, monitoring, and evaluation, with emphasis on their relationships, assumptions, analytical use, and application within Climate Change Law and Policy.', 'MSD_COURSE_052_M7', 'Active'), ('MOD_COURSE_053_M1', 'Contract Formation', '1', 'Examines the concepts and methods required to understand and work with contract formation. The module addresses offer, acceptance, consideration, intention, capacity, and consent, with emphasis on their relationships, assumptions, analytical use, and application within Contract Law and Commercial Agreements.', 'MSD_COURSE_053_M1', 'Active'), ('MOD_COURSE_053_M2', 'Contract Terms and Interpretation', '2', 'Examines the concepts and methods required to understand and work with contract terms and interpretation. The module addresses express terms, implied terms, conditions and warranties, interpretation, and exclusion clauses, with emphasis on their relationships, assumptions, analytical use, and application within Contract Law and Commercial Agreements.', 'MSD_COURSE_053_M2', 'Active'), ('MOD_COURSE_053_M3', 'Performance and Discharge', '3', 'Examines the concepts and methods required to understand and work with performance and discharge. The module addresses performance, frustration, novation, alteration, and discharge by agreement, with emphasis on their relationships, assumptions, analytical use, and application within Contract Law and Commercial Agreements.', 'MSD_COURSE_053_M3', 'Active'), ('MOD_COURSE_053_M4', 'Breach and Remedies', '4', 'Examines the concepts and methods required to understand and work with breach and remedies. The module addresses anticipatory breach, damages, specific performance, injunctions, and restitution, with emphasis on their relationships, assumptions, analytical use, and application within Contract Law and Commercial Agreements.', 'MSD_COURSE_053_M4', 'Active'), ('MOD_COURSE_053_M5', 'Commercial Risk Allocation', '5', 'Examines the concepts and methods required to understand and work with commercial risk allocation. The module addresses indemnities, limitation clauses, guarantees, force majeure, and insurance clauses, with emphasis on their relationships, assumptions, analytical use, and application within Contract Law and Commercial Agreements.', 'MSD_COURSE_053_M5', 'Active'), ('MOD_COURSE_053_M6', 'Contract Drafting and Negotiation', '6', 'Examines the concepts and methods required to understand and work with contract drafting and negotiation. The module addresses definitions, representations, covenants, schedules, and negotiation strategy, with emphasis on their relationships, assumptions, analytical use, and application within Contract Law and Commercial Agreements.', 'MSD_COURSE_053_M6', 'Active'), ('MOD_COURSE_053_M7', 'Commercial Agreements in Practice', '7', 'Examines the concepts and methods required to understand and work with commercial agreements in practice. The module addresses sale of goods, services, technology agreements, confidentiality, and dispute clauses, with emphasis on their relationships, assumptions, analytical use, and application within Contract Law and Commercial Agreements.', 'MSD_COURSE_053_M7', 'Active'), ('MOD_COURSE_054_M1', 'Employment Relationship and Conditions', '1', 'Examines the concepts and methods required to understand and work with employment relationship and conditions. The module addresses employment status, appointment terms, working conditions, and standing orders, with emphasis on their relationships, assumptions, analytical use, and application within Labour and Employment Law.', 'MSD_COURSE_054_M1', 'Active'), ('MOD_COURSE_054_M2', 'Wages and Benefits', '2', 'Examines the concepts and methods required to understand and work with wages and benefits. The module addresses wage regulation, deductions, bonus, social security, and leave, with emphasis on their relationships, assumptions, analytical use, and application within Labour and Employment Law.', 'MSD_COURSE_054_M2', 'Active'), ('MOD_COURSE_054_M3', 'Industrial Relations', '3', 'Examines the concepts and methods required to understand and work with industrial relations. The module addresses trade unions, collective bargaining, industrial disputes, and strikes and lockouts, with emphasis on their relationships, assumptions, analytical use, and application within Labour and Employment Law.', 'MSD_COURSE_054_M3', 'Active'), ('MOD_COURSE_054_M4', 'Occupational and Workplace Regulation', '4', 'Examines the concepts and methods required to understand and work with occupational and workplace regulation. The module addresses workplace safety, working hours, welfare, and employer duties, with emphasis on their relationships, assumptions, analytical use, and application within Labour and Employment Law.', 'MSD_COURSE_054_M4', 'Active'), ('MOD_COURSE_054_M5', 'Equality and Workplace Rights', '5', 'Examines the concepts and methods required to understand and work with equality and workplace rights. The module addresses non-discrimination, harassment, maternity protections, and reasonable workplace protections, with emphasis on their relationships, assumptions, analytical use, and application within Labour and Employment Law.', 'MSD_COURSE_054_M5', 'Active'), ('MOD_COURSE_054_M6', 'Dispute Resolution and Adjudication', '6', 'Examines the concepts and methods required to understand and work with dispute resolution and adjudication. The module addresses conciliation, labour authorities, tribunals, and judicial remedies, with emphasis on their relationships, assumptions, analytical use, and application within Labour and Employment Law.', 'MSD_COURSE_054_M6', 'Active'), ('MOD_COURSE_054_M7', 'Contemporary Employment Issues', '7', 'Examines the concepts and methods required to understand and work with contemporary employment issues. The module addresses platform work, fixed-term work, contract labour, remote work, and compliance systems, with emphasis on their relationships, assumptions, analytical use, and application within Labour and Employment Law.', 'MSD_COURSE_054_M7', 'Active'), ('MOD_COURSE_055_M1', 'Corporate Governance', '1', 'Examines the legal concepts, institutional mechanisms, procedures, and accountability issues governing corporate governance. The module addresses company organs, governance structures, shareholder rights, and disclosure, with emphasis on their relationships, assumptions, analytical use, and application within Corporate, Sustainability and ESG Law.', 'MSD_COURSE_055_M1', 'Active'), ('MOD_COURSE_055_M2', 'Directors Duties and Accountability', '2', 'Examines the concepts and methods required to understand and work with directors duties and accountability. The module addresses fiduciary duties, care, conflict management, and related-party transactions, with emphasis on their relationships, assumptions, analytical use, and application within Corporate, Sustainability and ESG Law.', 'MSD_COURSE_055_M2', 'Active'), ('MOD_COURSE_055_M3', 'Environmental and Social Responsibilities', '3', 'Examines the concepts and methods required to understand and work with environmental and social responsibilities. The module addresses corporate environmental duties, labour rights, community impacts, and supply-chain responsibility, with emphasis on their relationships, assumptions, analytical use, and application within Corporate, Sustainability and ESG Law.', 'MSD_COURSE_055_M3', 'Active'), ('MOD_COURSE_055_M4', 'ESG Disclosure and Reporting', '4', 'Examines the concepts and methods required to understand and work with esg disclosure and reporting. The module addresses materiality, non-financial disclosure, sustainability reporting, and assurance concepts, with emphasis on their relationships, assumptions, analytical use, and application within Corporate, Sustainability and ESG Law.', 'MSD_COURSE_055_M4', 'Active'), ('MOD_COURSE_055_M5', 'Sustainable Finance and Corporate Risk', '5', 'Examines the concepts and methods required to understand and work with sustainable finance and corporate risk. The module addresses green finance, climate risk, transition risk, and due diligence, with emphasis on their relationships, assumptions, analytical use, and application within Corporate, Sustainability and ESG Law.', 'MSD_COURSE_055_M5', 'Active'), ('MOD_COURSE_055_M6', 'Corporate Compliance and Enforcement', '6', 'Examines the concepts and methods required to understand and work with corporate compliance and enforcement. The module addresses compliance programs, investigations, whistleblowing, and sanctions, with emphasis on their relationships, assumptions, analytical use, and application within Corporate, Sustainability and ESG Law.', 'MSD_COURSE_055_M6', 'Active'), ('MOD_COURSE_055_M7', 'ESG Legal Practice and Disputes', '7', 'Examines the legal concepts, institutional mechanisms, procedures, and accountability issues governing esg legal practice and disputes. The module addresses greenwashing, stakeholder claims, disclosure liability, and contractual ESG clauses, with emphasis on their relationships, assumptions, analytical use, and application within Corporate, Sustainability and ESG Law.', 'MSD_COURSE_055_M7', 'Active'), ('MOD_COURSE_056_M1', 'Sociological Theory', '1', 'Examines the concepts and methods required to understand and work with sociological theory. The module addresses classical theory, functionalism, conflict theory, and symbolic interactionism, with emphasis on their relationships, assumptions, analytical use, and application within Sociology.', 'MSD_COURSE_056_M1', 'Active'), ('MOD_COURSE_056_M2', 'Social Institutions', '2', 'Examines the concepts and methods required to understand and work with social institutions. The module addresses family, education, religion, economy, polity, and institutional change, with emphasis on their relationships, assumptions, analytical use, and application within Sociology.', 'MSD_COURSE_056_M2', 'Active'), ('MOD_COURSE_056_M3', 'Culture and Socialization', '3', 'Examines the concepts and methods required to understand and work with culture and socialization. The module addresses culture, norms, values, identity, socialization, and deviance, with emphasis on their relationships, assumptions, analytical use, and application within Sociology.', 'MSD_COURSE_056_M3', 'Active'), ('MOD_COURSE_056_M4', 'Stratification and Inequality', '4', 'Examines the concepts and methods required to understand and work with stratification and inequality. The module addresses class, status, gender, race/ethnicity as social structure, mobility, and poverty, with emphasis on their relationships, assumptions, analytical use, and application within Sociology.', 'MSD_COURSE_056_M4', 'Active'), ('MOD_COURSE_056_M5', 'Groups, Organizations and Networks', '5', 'Examines the concepts and methods required to understand and work with groups, organizations and networks. The module addresses primary/secondary groups, organizations, bureaucracy, and social networks, with emphasis on their relationships, assumptions, analytical use, and application within Sociology.', 'MSD_COURSE_056_M5', 'Active'), ('MOD_COURSE_056_M6', 'Population, Urbanization and Social Change', '6', 'Examines the concepts and methods required to understand and work with population, urbanization and social change. The module addresses demography, migration, urbanization, globalization, and social movements, with emphasis on their relationships, assumptions, analytical use, and application within Sociology.', 'MSD_COURSE_056_M6', 'Active'), ('MOD_COURSE_056_M7', 'Contemporary Sociological Analysis', '7', 'Develops the analytical methods used to formulate, solve, and evaluate problems contemporary sociological analysis. The module addresses digital society, institutions and technology, comparative analysis, and mixed-method sociology, with emphasis on their relationships, assumptions, analytical use, and application within Sociology.', 'MSD_COURSE_056_M7', 'Active'), ('MOD_COURSE_057_M1', 'Social Cognition', '1', 'Examines the concepts and methods required to understand and work with social cognition. The module addresses schemas, attribution, heuristics, social perception, and judgment, with emphasis on their relationships, assumptions, analytical use, and application within Social Psychology.', 'MSD_COURSE_057_M1', 'Active'), ('MOD_COURSE_057_M2', 'Attitudes and Persuasion', '2', 'Examines the concepts and methods required to understand and work with attitudes and persuasion. The module addresses attitude formation, cognitive dissonance, persuasion models, and resistance, with emphasis on their relationships, assumptions, analytical use, and application within Social Psychology.', 'MSD_COURSE_057_M2', 'Active'), ('MOD_COURSE_057_M3', 'Interpersonal Processes', '3', 'Examines the concepts and methods required to understand and work with interpersonal processes. The module addresses attraction, relationships, prosocial behaviour, aggression, and conflict, with emphasis on their relationships, assumptions, analytical use, and application within Social Psychology.', 'MSD_COURSE_057_M3', 'Active'), ('MOD_COURSE_057_M4', 'Groups and Collective Behaviour', '4', 'Examines the concepts and methods required to understand and work with groups and collective behaviour. The module addresses group norms, conformity, obedience, group decision-making, and collective action, with emphasis on their relationships, assumptions, analytical use, and application within Social Psychology.', 'MSD_COURSE_057_M4', 'Active'), ('MOD_COURSE_057_M5', 'Identity and Intergroup Relations', '5', 'Examines the concepts and methods required to understand and work with identity and intergroup relations. The module addresses social identity, categorization, prejudice, stereotyping, and intergroup conflict, with emphasis on their relationships, assumptions, analytical use, and application within Social Psychology.', 'MSD_COURSE_057_M5', 'Active') ON CONFLICT DO NOTHING;